			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
