; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE). An Integer address is sign extended:
; 0-32767 = the ROM's first 32K, -32768..-1 = RAM $FF8000-$FFFFFF
; (where the variables are). DEEK / DOKE need an even address.
; ============================================================

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
kw_sc_end:
			tst.b (a1)
			beq kw_sc_copy
			addq.l #1, a1
			subq.w #1, d1
			bgt kw_sc_end
			rts
kw_sc_copy:
			tst.w d1
			beq kw_sc_none
			subq.w #1, d1
kw_sc_lp:
			move.b (a0)+, (a1)+
			dbeq d1, kw_sc_lp
			beq kw_sc_none
			clr.b (a1)
kw_sc_none:
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
